/**
 * BSI Stand-der-Technik-Bibliothek loader (ADR-0005, ADR-0039). The manifest (library-index.json,
 * generated by tools/gen-library-index.mjs) is bundled so the index is available at startup;
 * artifact bodies are fetched lazily from BSI's live `main` on raw.githubusercontent.com,
 * validated (ADR-0003), and cached in IndexedDB keyed by path+sha. Fetches degrade gracefully to
 * cached content with a warning, never a hard crash (ADR-0002); every failure is logged with
 * decision_ids and surfaced as a structured `UpstreamProblem` (ADR-0039). Library artifacts are
 * read-only (origin `library`); `adopt` copies one into the workspace as an editable `user`
 * artifact with a new uuid. Entry kinds TALOS cannot open yet (mapping collections, PO Q11) are
 * listed but not adoptable.
 *
 * Decision IDs: ADR-0005, ADR-0039, ADR-0002, ADR-0003, ADR-0004.
 */
import { getDb, type LibraryCacheEntry } from './db';
import { ArtifactRepository } from './artifactRepository';
import {
  fetchUpstream,
  reportUpstreamFailure,
  toUpstreamProblem,
  UpstreamLoadError,
  type UpstreamFetchDeps,
  type UpstreamProblem,
} from './upstreamFetch';
import { parseOscalDocument } from '@/models/envelope';
import { OSCAL_WRAPPER_KEYS, type OscalArtifactType } from '@/models/oscalBase';
import { libraryRawUrl } from '@/config';
import manifestJson from './library-index.json';

/**
 * Library categories (ADR-0039 mapping of BSI's layout): resolved/standalone catalogs are
 * Anwenderkataloge, catalogs imported by a BSI profile are Quellkataloge. Unknown future values
 * are tolerated (shown under the advanced toggle).
 */
export type LibraryCategory =
  | 'Anwenderkatalog'
  | 'Quellkatalog'
  | 'Profil'
  | 'Komponente'
  | 'Mapping'
  | 'Assessment'
  | 'Sonstiges';

/** OSCAL root key of the file, e.g. `catalog`, `profile`, `mapping-collection`. */
export type LibraryArtifactKind = string;

export interface LibraryManifestEntry {
  path: string;
  artifactType: LibraryArtifactKind;
  title: string;
  category: LibraryCategory | string;
  sha: string;
  size: number;
}

export interface LibraryManifest {
  generatedAt: string;
  source: string;
  ref: string;
  /** Upstream commit the index was generated from (informational; content follows `ref`). */
  commit?: string;
  license: string;
  namespaces?: { targetObjectCategories: string; threats: string };
  entries: LibraryManifestEntry[];
}

/** The bundled library index (read at startup, ADR-0005). */
export function getLibraryManifest(): LibraryManifest {
  return manifestJson as LibraryManifest;
}

/** Categories shown without the advanced toggle (PLAT-002: user catalogs + components). */
export const DEFAULT_LIBRARY_CATEGORIES: ReadonlySet<string> = new Set(['Anwenderkatalog', 'Komponente']);

/** OSCAL root keys TALOS can adopt and edit from the library (ADR-0039). */
const ADOPTABLE_KINDS: ReadonlySet<string> = new Set(['catalog', 'profile', 'component-definition']);

/** True when TALOS can adopt this entry; false for e.g. mapping collections (PO Q11). */
export function isAdoptableLibraryEntry(entry: Pick<LibraryManifestEntry, 'artifactType'>): boolean {
  return ADOPTABLE_KINDS.has(entry.artifactType);
}

export interface LoadedLibraryArtifact {
  entry: LibraryManifestEntry;
  type: OscalArtifactType;
  /** camelCase app model. */
  artifact: unknown;
  /** raw OSCAL wrapper document as fetched (for provenance / re-parse on adopt). */
  document: unknown;
  fromCache: boolean;
  /** non-blocking warning (e.g. served stale from cache), English; see `problem` for i18n. */
  warning?: string;
  /** structured reason for `warning` (ADR-0039). */
  problem?: UpstreamProblem;
}

export interface LibraryDeps extends UpstreamFetchDeps {
  now?: () => string;
}

async function getCached(path: string): Promise<LibraryCacheEntry | undefined> {
  const db = await getDb();
  return db.get('libraryCache', path);
}

async function putCached(entry: LibraryCacheEntry): Promise<void> {
  const db = await getDb();
  await db.put('libraryCache', entry);
}

/** Validate a fetched document and confirm it is the artifact type the manifest promised. */
function parseAndCheck(entry: LibraryManifestEntry, document: unknown) {
  const { type, artifact } = parseOscalDocument(document);
  if (OSCAL_WRAPPER_KEYS[type] !== entry.artifactType) {
    throw new Error(
      `Library file ${entry.path} is a ${OSCAL_WRAPPER_KEYS[type]}, expected ${entry.artifactType}.`,
    );
  }
  return { type, artifact };
}

/**
 * Load a library artifact: cache hit by path+sha, else fetch + validate + cache. On a fetch
 * failure, fall back to any cached copy (even a stale sha) with a warning; only throw when there
 * is nothing cached.
 */
export async function loadLibraryArtifact(
  entry: LibraryManifestEntry,
  deps: LibraryDeps = {},
): Promise<LoadedLibraryArtifact> {
  const now = deps.now ?? (() => new Date().toISOString());
  if (!isAdoptableLibraryEntry(entry)) {
    throw new Error(`TALOS does not support "${entry.artifactType}" library files yet.`);
  }
  const cached = await getCached(entry.path);
  if (cached && cached.sha === entry.sha) {
    const { type, artifact } = parseAndCheck(entry, cached.document);
    return { entry, type, artifact, document: cached.document, fromCache: true };
  }

  const url = libraryRawUrl(entry.path);
  try {
    const document = await fetchUpstream(url, 'json', deps);
    const { type, artifact } = parseAndCheck(entry, document);
    await putCached({
      path: entry.path,
      sha: entry.sha,
      artifactType: type,
      title: entry.title,
      fetchedAt: now(),
      document,
    });
    return { entry, type, artifact, document, fromCache: false };
  } catch (fetchErr) {
    const problem = toUpstreamProblem('library-artifact', url, fetchErr, { title: entry.title });
    if (cached) {
      const { type, artifact } = parseAndCheck(entry, cached.document);
      const withCache = { ...problem, cachedAt: cached.fetchedAt };
      reportUpstreamFailure(withCache, true);
      const reason = problem.status === 404 ? `moved or removed upstream (HTTP 404)` : 'offline or unreachable';
      return {
        entry,
        type,
        artifact,
        document: cached.document,
        fromCache: true,
        warning: `Offline: showing a cached copy of "${entry.title}" (${cached.sha === entry.sha ? 'current' : 'possibly outdated'}; ${reason}).`,
        problem: withCache,
      };
    }
    reportUpstreamFailure(problem, false);
    throw new UpstreamLoadError(
      `Could not load "${entry.title}" from the BSI library and no cached copy exists: ${problem.detail}`,
      problem,
    );
  }
}

/**
 * Adopt a loaded library artifact into the workspace: a fresh copy with a new uuid and
 * `origin: user` so it is editable (ADR-0005). Returns the new uuid.
 */
export async function adoptLibraryArtifact(loaded: LoadedLibraryArtifact): Promise<string> {
  const { type, document } = loaded;
  const { artifact } = parseOscalDocument<{ uuid: string }>(document);
  const uuid = globalThis.crypto.randomUUID();
  artifact.uuid = uuid;
  await ArtifactRepository.forType<{ uuid: string }>(type).create({
    uuid,
    type,
    origin: 'user',
    artifact,
  });
  return uuid;
}
